void resolveTriangleType(ShapeField.DecodedTriangle triangle) {
  // Confirm the field type describes a legal BKD layout before collapsing vertices.
  Objects.requireNonNull(
      new BKDConfig(
          dimensionCount,
          indexDimensionCount,
          dimensionNumBytes,
          BKDConfig.DEFAULT_MAX_POINTS_IN_LEAF_NODE));

  if (triangle.aX == triangle.bX && triangle.aY == triangle.bY) {
    if (triangle.aX == triangle.cX && triangle.aY == triangle.cY) {
      triangle.type = ShapeField.DecodedTriangle.TYPE.POINT;
    } else {
      triangle.bX = triangle.cX;
      triangle.bY = triangle.cY;
      triangle.cX = triangle.aX;
      triangle.cY = triangle.aY;
      triangle.ab = triangle.ca;
      triangle.type = ShapeField.DecodedTriangle.TYPE.LINE;
    }
  } else if (triangle.aX == triangle.cX && triangle.aY == triangle.cY) {
    triangle.type = ShapeField.DecodedTriangle.TYPE.LINE;
  } else if (triangle.bX == triangle.cX && triangle.bY == triangle.cY) {
    triangle.cX = triangle.aX;
    triangle.cY = triangle.aY;
    triangle.type = ShapeField.DecodedTriangle.TYPE.LINE;
  } else {
    triangle.type = ShapeField.DecodedTriangle.TYPE.TRIANGLE;
  }
}

